ls -la /root/pwt110_meta.json 2>&1 && python3 -c "
import json
with open('/root/pwt110_meta.json') as f:
    meta = json.load(f)
# Look for rnna and cn descriptions
if 'columns' in meta:
    for col_name in ['rnna', 'cn']:
        if col_name in meta['columns']:
            print(f'{col_name}:')
            info = meta['columns'][col_name]
            for k,v in info.items():
                if k != 'sources' and k != 'origins':
                    print(f'  {k}: {v}')
            print()
elif 'variables' in meta:
    for var in meta.get('variables', {}).keys():
        if var in ['rnna', 'cn']:
            print(f'{var}: {json.dumps(meta[\"variables\"][var], indent=2)[:500]}')
else:
    print('Keys:', list(meta.keys())[:20])
    print(json.dumps(meta, indent=2)[:2000])
" 2>&1

python3 -c "
import json
with open('/root/pwt110_meta.json') as f:
    meta = json.load(f)

for col_name in ['rnna', 'cn']:
    if col_name in meta.get('fields', {}):
        info = meta['fields'][col_name]
        print(f'=== {col_name} ===')
        for k in ['title', 'description', 'unit', 'short_unit', 'display']:
            if k in info:
                print(f'  {k}: {info[k]}')
        if 'processing_level' in info:
            print(f'  processing_level: {info[\"processing_level\"]}')
        print()
" 2>&1

